<template><main class="login"><section class="login-card"><div><h1>EcomAgent</h1><p>单商家私有化经营辅助系统</p></div><el-alert v-if="usingMock" title="P0 本地 Mock 账号：admin、operator_content、customer_service（密码仅用于 Mock 演示）；顾客为匿名咨询入口，不登录后台。" type="info" :closable="false" /><el-form :model="form" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="form.username" autocomplete="username" /></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password autocomplete="current-password" /></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-button native-type="submit" type="primary" :loading="loading" class="login-button">登录</el-button></el-form></section></main></template>
<script setup lang="ts">import { reactive, ref } from "vue"; import { useRoute, useRouter } from "vue-router"; import { useAuthStore } from "../stores/auth"; import { errorMessage, usingMock } from "../api/client";
const router=useRouter(), route=useRoute(), auth=useAuthStore(); const loading=ref(false),error=ref(""); const form=reactive({username:"operator_content",password:""});
async function submit(){ error.value=""; if(!form.username||!form.password){error.value="请填写账号和密码";return;} loading.value=true;try{await auth.login(form.username,form.password); const fallback=auth.user?.role==="customer_service"?"/service":"/products"; router.push(typeof route.query.redirect==="string"?route.query.redirect:fallback);}catch(e){error.value=errorMessage(e)}finally{loading.value=false} }</script>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#e8f1ed,#f7f5ee)}.login-card{width:min(440px,calc(100vw - 32px));padding:34px;background:#fff;border:1px solid #dbe5df;border-radius:10px;box-shadow:0 20px 50px #17312b1c}.login-card h1{margin:0;color:#17312b}.login-card p{margin:6px 0 22px;color:#66766f}.login-card :deep(.el-alert){margin-bottom:18px}.login-button{width:100%;margin-top:8px}</style>
